if (configElement) {
  const entries = JSON.parse(configElement.textContent)
  const [{ Interact }, legacyPresets, presets] = await Promise.all([
    import(`https://cdn.jsdelivr.net/npm/@wix/interact@2.8.2/dist/es/web.min.js`),
    import(`https://cdn.jsdelivr.net/npm/@wix/wix-motion-presets@1.10.0/+esm`),
    import(`https://cdn.jsdelivr.net/npm/@wix/motion-presets@1.1.0/dist/browser/motion-presets.min.js`),
  ])
  if (configElement.isConnected) {
    const aliasedLegacyPresets = {}
    for (const name of Object.keys(legacyPresets)) {
      aliasedLegacyPresets[`LEGACY_` + name] = legacyPresets[name]
    }
    Interact.registerEffects({ ...presets, ...aliasedLegacyPresets })
    Interact.forceReducedMotion = false
    Interact.setup({
      scrollOptionsGetter: function () {
        return document.getElementById(`site-root`)
      },
      allowA11yTriggers: true,
      viewEnter: {
        useSafeViewEnter: true,
      },
    })
    entries.forEach(function (entry, index) {
      const options = {
        configIndex: entries.length === 1 ? undefined : index,
        reducedMotionPolicy: entry.reducedMotionPolicy,
      }
      if (!entry.disableQuery) {
        Interact.create(entry.config, options)
        return
      }
      const disabled = window.matchMedia(entry.disableQuery)
      let instance
      const stop = function () {
        if (instance) {
          instance.destroy()
          instance = undefined
        }
      }
      const update = function () {
        if (disabled.matches) {
          stop()
        } else if (!instance) {
          instance = Interact.create(entry.config, options)
        }
      }
      update()
      disabled.addEventListener(`change`, update)
      configElement.addEventListener(`interactions-teardown`, function () {
        disabled.removeEventListener(`change`, update)
        stop()
      }, { once: true })
    })
  }
}</script><div id="main_MF" class="main_MF"><div id="SCROLL_TO_TOP" class="qe3oTb ignore-focus SCROLL_TO_TOP" role="region" tabindex="-1" aria-label="top of page"><span class="TvbeET">top of page</span></div><div id="site-root" class="site-root"><div id="masterPage" class="masterPage css-editing-scope"><div id="SITE_PAGES" class="Y3K28_ SITE_PAGES"><div id="c1dmp" class="ETqrjz theme-vars c1dmp"><div class="g0IvTF wixui-page" data-testid="page-bg"></div><div><div class="c1dmp-overflow-wrapper ku1hVK" data-testid="responsive-container-overflow"><div data-testid="responsive-container-content" tabindex="-1" role="group" class="c1dmp-container"><div id="c1dmp-background-layer" class="J6ODx c1dmp-background-layer"><div class="builder-root builder-root comp-muwfybnd _background_x7ip3_1 _mask_x7ip3_35 background" id="comp-muwfybnd" data-motion-part="BG_LAYER comp-muwfybnd"></div></div><header id="comp-mb7ogqrp" class="comp-mb7ogqrp S829f_ comp-mb7ogqrp-container" slots="[object Object]" wix="[object Object]"><section id="comp-mb7ogqrp_r_comp-mb7ogqqn" tabindex="-1" data-block-level-container="Section" class="ke5pl1 comp-mb7ogqrp_r_comp-mb7ogqqn-container section comp-mb7ogqrp_r_comp-mb7ogqqn ke5pl1 yEgiaI wixui-header undefined fwXYgt" data-testid="section-container"><div id="comp-mb7ogqrp_r_comp-mdr142kt" class="container _internalContainerRoot_1xyyz_1 builder-root theme-vars builder-root theme-vars comp-mb7ogqrp_r_comp-mdr142kt" data-testid="internal-container-root"><div class="_backgroundLayer_1xyyz_25" data-testid="internal-container-background-layer"><div class="builder-root builder-root comp-mb7ogqrp_r_comp-mhs1biva _background_x7ip3_1 _mask_x7ip3_35 background" id="comp-mb7ogqrp_r_comp-mhs1biva" data-motion-part="BG_LAYER comp-mb7ogqrp_r_comp-mhs1biva"></div></div><div data-testid="internal-container-content" role="group" class="comp-mb7ogqrp_r_comp-mdr142kt-container max-width-container"><div id="comp-mb7ogqrp_r_comp-mvza56u4" class="logo-wrapper _logo_ackza_1 buil